{
  "summary": "In March 2025 payments-pgbouncer-01 hit 100% CPU on its single core, causing client queues and PAYAPI‑E1042 errors from the payments API.",
  "likely_cause": "PgBouncer process saturated CPU, leading to client wait queues and connection acquire timeouts.",
  "confidence": "high",
  "claims": [
    {
      "text": "PgBouncer on payments-pgbouncer-01 was at 100% CPU of one core.",
      "evidence_ids": ["INC-0026#1"],
      "quote": "top showed the PgBouncer process at 100% of one core."
    },
    {
      "text": "When clients could not get a pooled connection within 500 ms they logged PAYAPI‑E1042.",
      "evidence_ids": ["INC-0026#0"],
      "quote": "Requests that could not get a pooled connection within 500 ms logged PAYAPI-E1042"
    },
    {
      "text": "PgBouncer is a single‑process using one core, so CPU saturation caps its throughput.",
      "evidence_ids": ["RB-011#3"],
      "quote": "PgBouncer is a single process using one core."
    },
    {
      "text": "Step 1: Count clients per instance to see if connections exceed expected numbers.",
      "evidence_ids": ["RB-011#3"],
      "quote": "Count clients per instance."
    },
    {
      "text": "Step 2: Look at the pools on both instances (SHOW POOLS) to check cl_waiting and maxwait.",
      "evidence_ids": ["RB-011#2"],
      "quote": "Look at the pools on both instances."
    },
    {
      "text": "Step 3: Verify PgBouncer CPU is well below 100% when healthy.",
      "evidence_ids": ["RB-011#3"],
      "quote": "Expected: well below 100% CPU."
    },
    {
      "text": "Step 4: Find long‑running statements on the database that hold server connections.",
      "evidence_ids": ["RB-011#4"],
      "quote": "Find what holds the server connections."
    },
    {
      "text": "Step 5: Confirm PostgreSQL still has connection capacity.",
      "evidence_ids": ["RB-011#5"],
      "quote": "Confirm Postgres still has room."
    },
    {
      "text": "Step 6: Remove the load by stopping the offending feature or job and canceling stray transactions.",
      "evidence_ids": ["RB-011#5"],
      "quote": "Stop whatever owns the long transactions"
    },
    {
      "text": "Step 7: Verify cl_waiting and maxwait return to zero and PAYAPI‑E1042 disappears.",
      "evidence_ids": ["RB-011#6"],
      "quote": "Verify. cl_waiting 0 and maxwait 0 on both instances, PAYAPI-E1042 back to zero"
    }
  ],
  "next_checks": [
    "Collect current PgBouncer CPU usage per instance.",
    "Run SHOW CLIENTS on both PgBouncer instances.",
    "Run SHOW POOLS and record cl_waiting and maxwait values.",
    "Query pg_stat_activity for long‑running statements on payments-db.",
    "Check PostgreSQL max_connections and current client backend count."
  ]
}
